// Pull the single source of truth into this repo. Nothing in data/ or the
// packages' generated files is edited by hand.
//   node scripts/export.mjs [--site C:/BF/Git/Wimsta-formulas] [--registry <url|file>] [--openapi <url|file>]
import { readFileSync, writeFileSync, copyFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const arg = (k, d) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const site = arg('--site', '../Wimsta-formulas');
const load = async (src) => (/^https?:/.test(src) ? (await fetch(src)).json() : JSON.parse(readFileSync(src, 'utf8')));

const registry = await load(arg('--registry', 'https://wimsta.com/api/registry.json'));
const openapi = await load(arg('--openapi', 'https://wimsta.com/api/openapi.json'));

// 1. data/registry.json — byte copy of the API document
writeFileSync(join(root, 'data/registry.json'), JSON.stringify(registry, null, 2) + '\n');

// 2. input bounds — the same min/max as /api/calc (union over all calc endpoints)
const bounds = {};
for (const [p, ops] of Object.entries(openapi.paths)) {
  if (!p.startsWith('/api/calc/')) continue;
  for (const prm of ops.get?.parameters ?? []) {
    const s = prm.schema ?? {};
    if (typeof s.minimum === 'number') bounds[prm.name] = { min: s.minimum, max: s.maximum };
  }
}
const keep = ['age', 'height_cm', 'weight_kg', 'waist_cm', 'abdomen_cm', 'neck_cm', 'hip_cm', 'wrist_cm', 'forearm_cm', 'thigh_cm', 'calf_cm', 'body_fat_pct'];
const B = Object.fromEntries(keep.map((k) => [k, bounds[k]]));
if (keep.some((k) => !B[k])) throw new Error('bound missing in openapi: ' + keep.filter((k) => !B[k]));
writeFileSync(join(root, 'data/bounds.json'), JSON.stringify(B, null, 2) + '\n');

// 3. JS package: equations verbatim from the site + generated data module
copyFileSync(join(site, 'src/lib/formulas/registry-formulas.ts'), join(root, 'packages/js/src/formulas.ts'));
writeFileSync(join(root, 'packages/js/src/data.ts'),
  '// GENERATED by scripts/export.mjs — do not edit.\n' +
  "import type { Registry } from './types.js';\n" +
  `export const registry: Registry = ${JSON.stringify(registry, null, 2)};\n` +
  `export const BOUNDS: Record<string, { min: number; max: number }> = ${JSON.stringify(B, null, 2)};\n`);

// 4. Python package data
for (const f of ['registry.json', 'bounds.json'])
  copyFileSync(join(root, 'data', f), join(root, 'packages/python/src/wimsta_formulas/data', f));

// 5. README, licences and NOTICE inside each package
for (const dir of ['packages/js', 'packages/python']) {
  copyFileSync(join(root, 'README.md'), join(root, dir, 'README.md'));
  copyFileSync(join(root, 'LICENSE-CODE'), join(root, dir, 'LICENSE'));
  copyFileSync(join(root, 'LICENSE-DATA'), join(root, dir, 'LICENSE-DATA'));
  copyFileSync(join(root, 'NOTICE'), join(root, dir, 'NOTICE'));
}

console.log(`registry ${registry.registry_version}: ${registry.formula_count} formulas; bounds ${keep.length}`);
